import anywidget
import pandas as pd
import traitlets


class RangeLabelerDraft(anywidget.AnyWidget):
    _esm = "ai/draft_widget/static/widget.js"
    _css = "ai/draft_widget/static/widget.css"

    t = traitlets.List(traitlets.Float()).tag(sync=True)
    y = traitlets.List(traitlets.Float()).tag(sync=True)
    labels = traitlets.List(traitlets.Unicode()).tag(sync=True)
    active_label = traitlets.Unicode("").tag(sync=True)
    ranges = traitlets.List(traitlets.Dict()).tag(sync=True)

    def __init__(self, y, t=None, labels=("event",), **kwargs):
        if t is None:
            t = range(len(y))
        super().__init__(
            t=[float(v) for v in t],
            y=[float(v) for v in y],
            labels=list(labels),
            active_label=labels[0],
            **kwargs,
        )

    @property
    def ranges_df(self):
        return pd.DataFrame(self.ranges, columns=["start", "end", "label"])
